mapper.select:
select c.*,ha.*,d.name as domain_name,d.domain_id from consultant c
left join hou_admin ha on c.admin_id = ha.admin_id
left join consultant_domain cd on c.consultant_id = cd.consultant_id
left join domain d on cd.domain_id = d.domain_id

    ha.is_delete = 0

       and ha.status = 0


        and ha.status = #{consultantDO.status}


       and ha.name like concat('%',#{consultantDO.name},'%')


       and c.role = #{consultantDO.role}


       and c.price < #{consultantDO.price}


       and cd.domain_id = #{consultantDO.domainId}


        and c.admin_id = #{consultantDO.adminId}
